	void solve() {
		int n = scn.nextInt();
		int []a = scn.nextIntArray(n);
		int dp[] = new int[n];
		dp[0]=0;
		dp[1]=Math.abs(a[1]-a[0]);
		if(n==2)
		{
			out.println(dp[1]);
			return;
		}

		dp[2]=Math.min(dp[1]+Math.abs(a[2]-a[1]), dp[0]+Math.abs(a[2]-a[0]));
		for(int i =3;i<n;i++)
		{
			dp[i]=Math.min(dp[i-1]+Math.abs(a[i]-a[i-1]), dp[i-2]+Math.abs(a[i]-a[i-2]));

		}
		out.println(dp[n-1]);
	}

	int[][] packU(int n, int[] from, int[] to) {
		int[][] g = new int[n][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int t : to)
			p[t]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]];
		for (int i = 0; i < from.length; i++) {
			g[from[i]][--p[from[i]]] = to[i];
			g[to[i]][--p[to[i]]] = from[i];
		}
		return g;
