	static class Task{
		int M = (int) (1e9 + 7);
		public void solve(int testNumber, InputReader in, PrintWriter out) {
				int n = in.nextInt(), l = in.nextInt();
				int min = M, a, s = 0;
				for(int i = 0; ++i < n+1;) {
					a = l+i-1;
					s += a;
					if(Math.abs(a) < Math.abs(min)) min = a;
				}

				out.print(s - min);

		}//Solve



