    static class A {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int n = in.nextInt(), ac = 0, tle = 0, wa = 0, re = 0;
            while (n-- > 0) {
                String s = in.next();
                if (s.equals("AC")) ac++;
                if (s.equals("WA")) wa++;
                if (s.equals("TLE")) tle++;
                if (s.equals("RE")) re++;
            }
