	private void solveA() {
		Scanner scanner = null;

		try {
			scanner = new Scanner(System.in);
			int[] wk = new int[3];

			for (int i = 0; i < wk.length; i++) {
				wk[i] = scanner.nextInt();
			}

			Arrays.sort(wk);
			int res = Math.abs(wk[0] - wk[1]) + Math.abs(wk[1] - wk[2]);

			System.out.println(res);

		} finally {
			if (scanner != null) {
				scanner.close();
			}
		}
	}

	private void solveB() {
		Scanner scanner = null;
		String[] s;
		String[] t;

		try {
			scanner = new Scanner(System.in);
			s = scanner.next().split("");
			t = scanner.next().split("");

			HashMap<String, Integer> wk = new HashMap<String, Integer>();
			for (int i = 0; i < s.length; i++) {
				if (!s[i].equals("") && wk.containsKey(s[i])) {
					int cnt = wk.get(s[i]);
					wk.put(s[i], ++cnt);
				} else {
					wk.put(s[i], 1);
				}
				//				System.out.println(s[i]);
			}

			int fail = 0;
			for (int i = 0; i < t.length; i++) {
				if (wk.containsKey(t[i]) && wk.get(s[i]) > 0) {
					int cnt = wk.get(s[i]);
					wk.put(s[i], --cnt);
				} else {
					fail++;
				}
			}

			System.out.println(fail != 0 ? "No" : "Yes");

