public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double ans = 0;
        for(int i = 1; i <= n; i++){
            double tmp = 1d/(double)n;
            if(i >= k){
                ans += tmp;
                continue;
            }
            int now = i;
            while(now <= k){
                now *= 2;
                tmp /= 2;
            }
            ans += tmp;
        }
        System.out.println(ans);
    }
}

