class Solver {
    public void solve(String a, String b, String c) {
        String ans = "";
        char start = a.charAt(0);
        int aa = 1;
        int bb = 0;
        int cc = 0;

        while (a.length() > 0 || b.length() > 0 || c.length() > 0) {
            if (start == 'a') {
                aa++;
                start = a.charAt(aa);
            } else if (start == 'b') {
                bb++;
                start = b.charAt(bb);
            } else {
                cc++;
                start = c.charAt(cc);
            }
            if (aa == a.length() - 1) {
                ans = "A";
                break;
            } else if (bb == b.length() - 1) {
                ans = "B";
                break;
            } else if (cc == c.length() - 1) {
                ans = "C";
                break;
            }

        }
        Main.output.append(ans);
    }
}

