			h[i] = in.nextInt();
		}
		int dp[] = new int[N];
		Arrays.fill(dp, Integer.MAX_VALUE);
		dp[0] = 0;
		for (int i = 0; i < N; i++) {
			for (int j : new int[] { i + 1, i + 2 }) {
				if (j < N) {
					dp[j] = Math.min(dp[j], dp[i] + Math.abs(h[i] - h[j]));
