    static class B {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.ni(), m = in.ni(), c = in.ni();
            int[] b = in.na(m);
            int[][] a = new int[n][];
            for (int i = 0; i < n; i++) {
                a[i] = in.na(m);
            }
