public class Main {

  private void solve(InputReader in, PrintWriter out) {
    int n = in.nextInt();
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
      arr[i] = in.nextInt();
    }
    int count = 0;
    int countDivide = 0;
    while (true) {
      for (int i = 0; i < arr.length; i++) {
        if (arr[i] % 2 == 0 && countDivide == 0) {
          arr[i] = arr[i] / 2;
          countDivide++;
        } else {
          arr[i] = arr[i] * 3;
        }
      }
      if (countDivide == 0) {
        break;
      }
      countDivide = 0;
      count++;
    }
    out.println(count);
  }


