    public static boolean palindrome(String word)
    {
        String copy = "";
        for(int i = word.length(); i > 0; i--)
        {
            copy += word.substring(i-1,i);
        }
        if(word.equals(copy))
        {
            return true;
        }
        return false;
    }
}

