		int N = Integer.parseInt(tmp[0]);
		int K = Integer.parseInt(tmp[1]);

		double ans = 0;

		for (long  i = 1; i <= N; i++) {
			// iはさいころの目

			if (i >= K) {
				ans += 1.0/N;
