    int f(int n){
        if(n == 1) return 1;
        int ret = 2;
        for(int i = 2; i < Math.sqrt(n); i++){
            if(n % i == 0) ret += 2;
        }
        if(n % Math.sqrt(n) == 0) ret++;
        return ret;
    }


