		public void solve(int testNumber, MyScanner sc, PrintWriter out) {
			char[] S = sc.next().toCharArray();
			char[] T = sc.next().toCharArray();
			int ans = T.length;

			for (int i = 0; i + T.length <= S.length; i++) {
