		Arrays.fill(dp, Integer.MAX_VALUE);
		dp[0] = 0;

		for(int i = 0; i < n; i++)
		{
			if(i + 1 < n)dp[i + 1] = Math.min(dp[i] + (Math.abs(arr[i] - arr[i + 1])), dp[i + 1]);
