				ans += 2 * c;
			}
			x--;
		}
		if(a < 2 * c) {
			ans += a * x;
		} else {
			ans += 2 * c * x;
		}
		if(y % 2 == 1) {
			if(b < 2 * c) {
				ans += b;
			} else {
				ans += 2 * c;
			}
			y--;
		}
		if(b < 2 * c) {
			ans += b * y;
