	}
	static long gcd(long a,long b) {
		if(b==0) {
			return a;
		}
		return gcd(b,a%b);
	}
	static long solve(long b,long c,long d) {
		long ret = b;
		long other = c*d/gcd(c,d);
		ret-= b/c;
		ret -= b/d;
		ret += b/other;
		return ret;
	}

}

