        long sum = 0, residue = 0, ability;
        for (int i = 0; i < n + 1; i++) {
            if (i != n) {
                ability = b[i] + residue;
                residue = Math.min(ability - a[i], b[i]);
                residue = Math.max(residue, 0);
            } else {
                ability = residue;
            }

            if (a[i] < ability) {
                sum += a[i];
            } else {
                sum += ability;
            }
        }
        System.out.println(sum);
    }

}

