public class Main {
    public static MyScanner scan;
    public static PrintWriter out;
    public static void main(String[] args) {
        scan=new MyScanner();
        out=new PrintWriter(new BufferedOutputStream(System.out));

        int t=1;
//        int t=scan.nextInt();
        while(t-->0) {

            n=scan.nextInt();
            a=new long[n];
            memo=new HashMap<>();
            for(int c=0;c<n;c++) a[c]=scan.nextInt();
            out.println(dp(0));

        }
        out.close();
