    int C = sc.nextInt();
    int X = sc.nextInt();
    int Y = sc.nextInt();
    int costOp1 = A * X + B * Y;
    int Same = Math.min(X, Y);
    int costOp2 = Same * 2 * C + A * (X - Same) + B * (Y - Same);
