class Solver {
    public void solve(int N, String S) {
        int ans = 0;
        int cur = 'a';
        for (int i = 0; i < N; i++) {
            char c = S.charAt(i);
            if (cur == c) {
                cur++;
                if (cur > 'c') {
                    ans++;
                    cur = 'a';
                }
            }
            else {
                cur = 'a';
            }
        }
        System.out.println(ans);
    }
}

