		int[] dp = new int[N];
		dp[0] = 0;
		for(int i = 0;i < N;i++){
			h[i] = sc.nextInt();
		}
		dp[1] = Math.abs(h[1] - h[0]);
		for(int i = 1;i < N - 1;i++){
			int jump = Math.abs(h[i + 1] - h[i]);
