        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] b = new int[n-1];
        int min = Integer.MAX_VALUE;
        int sum = 0;
        int tmp = 0;
        for(int i = 0;i < n-1;i++){
