		long D = one.get(3);
		long BC = (B / C);
		long BD = (B / D);
		long BCD = (B / lcm(C, D));
		long Ball = B - (BC + BD) + BCD;

		long AC = (A / C);
		long AD = (A / D);
		long ACD = (A / lcm(C, D));
		long Aall = A - (AC + AD) + ACD;
		myout(Ball - Aall);

	}
