public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        int n = in.nextInt();
        int[][] grid = new int[2][n];
        for (int i = 0; i < 2; i++) {
            grid[i] = in.nextIntArray(n);
        }
        int max = 0;
        int sumBot = 0;
        for (int i=0; i<n; i++) {
            sumBot += grid[1][i];
        }
        int sumTop = grid[0][0];
        for (int i=0; i<n; i++) {
            max = sumBot + sumTop > max ? sumBot + sumTop : max;
            if (i != n - 1) {
                sumTop += grid[0][i + 1];
            }
            sumBot -= grid[1][i];
        }
        out.println(max);

        out.close();
        //INT OVERFLOW -> USE LONG
        //ARR OUT OF BOUNDS
    }

    static class Scanner {
