      }
      if(map.containsKey(t)) {
        map.put(t, map.get(t) + 1);
      } else {
        map.put(t, (long)1);
      }
    }
    long ans = 0;
    for(long key : map.keySet()) {
      long t = map.get(key);
      ans += ((t * (t - 1)) / 2);
    }
    System.out.println(ans);
  }
}

