        int n = sc.nextInt();
        int k = sc.nextInt();
        double ans = 0;
        for(int i = 1; i <= n; i++){
            long tmp = (long)n;
            if(i >= k){
                ans += 1d/tmp;
                continue;
            }
            int now = i;
            while(now <= k){
