  static class BBiteEating {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
      int n = in.nextInt(), l = in.nextInt();
      int L = l, R = l + n - 1;
      if (R < -L) {
        out.println(sum(L, R - 1));
      } else if (-L < R) {
        out.println(sum(L + 1, R));
      } else {
        out.println(sum(L, R));
      }
    }

    private int sum(int l, int r) {
      int n = r - l + 1;
      return n * (l + r) / 2;
    }

  }


