        if (x == 0) {
          break;
        }

        int[] eachdigit = new int[4];
        eachdigit[0] = x / 1000;
        eachdigit[1] = x /100 - 10 * eachdigit[0];
        eachdigit[3] = x % 10;
        eachdigit[2] = x % 10 /10;

        out.println(eachdigit[0]+eachdigit[1]+eachdigit[2]+eachdigit[3]);
      }

