        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));

        int k = Integer.parseInt(br.readLine());

        HashSet<Long> set = new HashSet<>();
        LinkedList<Long> q = new LinkedList<>();
        for (long i = 1; i <= 9; i++) {
            q.add(i);
            set.add(i);
        }

        if (k <= 9) {
            pw.println(k);
            pw.close();
            return;
        }

        while (!q.isEmpty()) {
            long head = q.poll();
            for (long i = head % 10 - 1; i <= head % 10 + 1; i++) {
                if (i < 0) continue;

                long val = head * 10 + i;
                if (set.contains(val)) continue;

                set.add(val);
                q.add(val);

                if (set.size() == k) {
                    pw.println(val);
                    pw.close();
                    return;
                }
            }
        }

        pw.close();
    }
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int[] monsters = new int [N + 1];
		int[] heros = new int [N];
		int temp = 0;
		int ans = 0;

		for(int i = 0; i < N + 1; i++) {
			monsters[i] = sc.nextInt();
		}

		for(int i = 0; i < N; i++) {
			heros[i] = sc.nextInt();
		}

		for(int i = 0; i < N; i++) {
			// i番目のモンスターを倒せるだけ倒す
			ans += Math.min(monsters[i], heros[i]);
			//　余力を計算
			temp = heros[i] - (monsters[i]);
			if(0 < temp) {
				//　余力がある場合はi+1番目のモンスターを倒す
				ans += Math.min(monsters[i + 1] , temp);
				monsters[i + 1] = monsters[i + 1] - Math.min(monsters[i + 1] , temp);	
			}
		}

		System.out.println(ans);
		sc.close();
	}
}

