			if (!(costTime[i][1] <= targetTime)) {
				continue;
			}

			if(ans > costTime[i][0]) {
				ans = costTime[i][0];
			}
		}

		if (ans == Integer.MAX_VALUE) {
			System.out.println("TLE");
		} else {

			System.out.println(ans);
		}

	}
}

