        int[] Sum2 = new int[N];
        int sum2 = 0;
        for (int i = N - 1; i >= 0; i--) {
            sum2 += A2i[i];
            Sum2[i] = sum2;
        }
        int result = 0;
        for (int i = 0; i < N; i++) {
            if (result < Sum1[i] + Sum2[i]) {
                result = Sum1[i] + Sum2[i];
            }
        }
        System.out.println(result);

    }
}

