  public static int minCost(int arr[], int pos, int dp[], int k){
  	if(pos >= arr.length)
      return Integer.MAX_VALUE;

     if(pos == arr.length -1)
      return 0;

    if(dp[pos] != Integer.MAX_VALUE)
      	return dp[pos];

    for(int i = pos+1; i<=pos+k; i++){
    if(i < arr.length)
      dp[pos] = Math.min(dp[pos], Math.abs(arr[pos] - arr[i]) + minCost(arr, i,dp, k));
    }

      return dp[pos];

  }
}

