            long n = Integer.parseInt(in.next());
            long k = Integer.parseInt(in.next());
            double ans = 0.0;

            for (long i = 1; i <= n; i++) {
                double tmp = 1.0;
                long nn = i;
                while (nn < k) {
                    nn *= 2;
                    tmp /= 2.0;
                }
                ans += tmp;
            }
            ans /= n;

            // 出力
            out.printf("%.12f\n", ans);

        }

    }
}

