            for(int hasNum : list.get(room)) {
                if(res[hasNum] != -1) {
                	continue;
                }
                res[hasNum] = room + 1;
                que.offer(hasNum);
            }
        }
        StringBuilder sb = new StringBuilder();
        System.out.println("Yes");
        for(int i = 1; i < res.length; i++) {
            sb.append(res[i] + "\n");
        }
