    count += b/e - (a-1)/e;
    System.out.println(count);

  }

  private static long lcm(long a, long b){
    long temp;
    long c = a;
    c *= b;
    while((temp = a%b)!=0){
      a=b;
      b=temp;
    }
    return c/b;
  }
}

