			sum = Math.min(2 * C * X + B * (Y - X), 2 * C * Y);
		} else {
			sum = Math.min(2 * C * Y + A * (X - Y), 2 * C * X);
		}
		System.out.println(A * X + B * Y > sum ? sum : A * X + B * Y);
	}
}

