public class Main {
    public static long gcd(long a, long b) {
        while (a % b != 0) {
            long tmp = a % b;
            a = b;
            b = tmp;
        }
        return b;
    }
    public static long lcm(long a, long b) {
        return a * b / gcd(a, b);
    }
    public static long divnum(long a, long b, long x) {
        return b / x - (a - 1) / x;
    }
