        Arrays.fill(dp, 1, n + 1, inf);
        System.out.println(Arrays.toString(dp));
        dp[1] = 0;
        for (int i = 1; i <= n; i++) {
          int[] a = {i + 1, i + 2};
          for (int j : a)
            if (j <= n) {
              dp[j] = Math.min(dp[j], dp[i] + Math.abs(h[i] - h[j]));
            }
        }
        System.out.println(dp[n]);
      } catch (Exception e){}
    }
  }
}

