			t[i]=sc.nextInt();
			x[i]=sc.nextInt();
			y[i]=sc.nextInt();
		}

		boolean ans = true;
		for(int i=1; i<=N; i++) {
			int dt = t[i] - t[i-1];
			int dist = Math.abs(x[i] - x[i-1]) + Math.abs(y[i] - y[i-1]);
			if(dt<dist) ans = false;
			if(dt%2 != dist%2) ans = false;
			if(!ans) break;
		}
		if (ans) System.out.println("Yes");
		else System.out.println("No");
		sc.close();
	}
