		Integer sen = -1;

		boolean judge = true;
		int i=0;
		do {
			int j=0;
			do {
				Integer tp = 5 * j + 1 * (m-i-j);
				if (tp == p - i * 10) {
					man = i;
					go = j;
					sen = m-i-j;
