import java.io.*;
public class Main {
    static int arr[];
    static long dp[][],mod=1000000007L;
    public static void main(String args[]) {
        Scanner input=new Scanner(System.in);
        int n=input.nextInt();
        int k=input.nextInt();
        arr=new int[n];
        long sum=0;
        for(int i=0;i<n;i++) {
            arr[i]=input.nextInt();
            sum+=arr[i];
        }
        if(sum<k) {
            System.out.println(0);
            System.exit(0);
        }
        Arrays.sort(arr);
        System.out.println(solve(n,k));
    }
    public static long solve(int n,int k) {
        dp=new long[n][k+1];
        for(int i=0;i<=arr[0];i++) {
            dp[0][i]=1;
        }
        for(int i=1;i<n;i++) {
            dp[i][0]=dp[i-1][0];
            for(int j=1;j<=arr[i];j++) {
                dp[i][j]=(dp[i][j-1]+dp[i-1][j])%mod;
            }
        }
        return dp[n-1][arr[n-1]];
    }
}

import java.util.Scanner;
class Main
{
  public static long knapsack(long[] wt, long[] val, long n, long w, long[][] dp)
  {
    for(int i = 1; i <= n; i++)
    {
      for(int j = 1; j <= w; j++)
      {
        if(wt[i - 1] <= j)
        {
          dp[i][j] = Math.max((val[i - 1] + dp[i - 1][j - wt[i - 1]]), dp[i - 1][j]);
        }
        else
                                                      {
                                                        dp[i][j] = dp[i - 1][j];
                                                      }


      }
    }
                                                      return dp[n][w];
  }
  public static void main(String[] args)
  {
    Scanner scan = new Scanner(System.in);
    int n = scan.nextInt();
    int w = scan.nextInt();
    long wt[] = new long[n];
    long val[] = new long[n];
    for(int i = 0; i < n; i++)
    {
      wt[i] = scan.nextlong();
      val[i] = scan.nextlong();
    }
    long[][] dp = new long[n + 1][w + 1];
    long maxProfit = knapsack(wt, val, n, w, dp);
    System.out.prlongln(maxProfit);
  }
}

