        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int N = readInt(reader);
            int[] P = readIntArray(reader);

            int c = 0;
            for (int i = 1; i < N - 1; i++) {
                if (P[i - 1] < P[i] && P[i] < P[i + 1]) {
                    c++;
                } else if (P[i - 1] > P[i] && P[i] > P[i + 1]) {
                    c++;
                }
            }

