		long count = 0;
		for (int i = 1; i + 1 < n; ++i) {
			if (check(p, i - 1, i, i + 1)) {
				++count;
			}
		}

		System.out.println(count);
		in.close();
	}

	static boolean check(int[] p, int i, int j, int k) {
		if (p[i] < p[j] && p[j] < p[k]) {
			return true;
		} else if (p[i] > p[j] && p[j] > p[k]) {
			return true;
		} else {
			return false;
		}
	}

}

