		long d = stdIn.nextLong();

		long cnt = b-b/c-b/d+b/lcm(c,d);

		long ccnt = (a-1)-(a-1)/c-(a-1)/d+(a-1)/lcm(c,d);

		long ans = cnt - ccnt;
		System.out.println(ans);

	}

}

