            for (int j = 0; j <= N - i; j++) {

                k = N - i - j;
                if (10000 * i + 5000 * j + 1000 * k == Y) {
                    out.println(i + " " + j + " " + k);
                    sc.close();
                    out.flush();
                    return;
                }
            }
        }

        out.println("-1 -1 -1");

        sc.close();
        out.flush();
    }
}

