        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] arr = in.nextIntArray(n);

            int[] dp = new int[n];
            dp[0] = 0;
            dp[1] = Math.abs(arr[1]-arr[0]);

            for(int i = 2; i < n; i++)
            {
                dp[i] = Math.min(dp[i-1]+Math.abs(arr[i]-arr[i-1]), dp[i-2]+Math.abs(arr[i]-arr[i-2]));
            }
            out.print(dp[n-1]);
        }
    }

